async function processEmployee(employee,method){if(!employee)return;const key=`${employee.id}_${$('attendanceAction').value}`;const now=Date.now();showNamedFeedback('Recognized',employee,method);if((lastSeen.get(key)||0)>now-2800)return;lastSeen.set(key,now);if(!employee.active){showNamedFeedback('Inactive employee',employee,'Attendance was not recorded.');return}const license=await ensureLicenseAccess();if(!license.allowed){showNamedFeedback('License verification required',employee,license.reason);notify(license.reason);return}const result=await recordAttendance(employee,method,$('attendanceAction').value,new Date(),attendanceSchedules);if(result.saved){syncNow();if($('attendanceAction').value==='checkin'){showSuccess(employee,result.record,method);beep();await renderDashboard()}else{showNamedFeedback('Check-out saved',employee,`${result.record.checkOut} • ${method}`);await renderDashboard()}}else if(result.duplicate)showNamedFeedback('Attendance Already Marked',employee,'Attendance is already recorded for today. Check the report for its status.');else if(result.duplicateCheckout)showNamedFeedback('Check-out already saved',employee,'Today’s check-out is already recorded.');else if(result.missingCheckIn)showNamedFeedback('Check-in required',employee,'Save today’s check-in before checking out.')}
function showFeedback(title,detail){const box=$('scanFeedback');box.classList.remove('recognized');box.innerHTML=`<span class="feedback-icon">✓</span><b>${escapeHtml(title)}</b><small>${escapeHtml(detail)}</small>`}
function showNamedFeedback(title,employee,detail){const box=$('scanFeedback');box.classList.add('recognized');box.innerHTML=`<span class="feedback-icon">✓</span><b>${escapeHtml(title)}</b><strong class="recognized-name">${escapeHtml(employee.name)}</strong><small>Employee ID: ${escapeHtml(employee.id)} • ${escapeHtml(detail)}</small>`}
function showSuccess(employee,record,method){$('toastName').textContent=employee.name;$('successToast').querySelector('b').textContent=record.status==='Late'?`Late · ${record.lateMinutes} min`:'Attendance Successful';$('toastMeta').textContent=`ID ${employee.id} • ${record.checkIn} • ${method}`;$('successToast').classList.add('show');showNamedFeedback(record.status==='Late'?'Late arrival':'Attendance Successful',employee,record.status==='Late'?`${record.checkIn} • scheduled ${record.scheduledTime} • ${record.lateMinutes} min late`:`${record.checkIn} • ${method}`);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('successToast').classList.remove('show'),1800)}
function categoryName(value){return ({peon:'Support Staff',management:'Management Staff',teaching:'Teaching Staff'})[value]||'Support Staff'}
async function loadSchedules(fillForm=false){const saved=await getSetting('attendance-schedule');if(saved?.value)attendanceSchedules={...attendanceSchedules,...saved.value};if(fillForm){$('timePeon').value=attendanceSchedules.peon;$('timeManagement').value=attendanceSchedules.management;$('timeTeaching').value=attendanceSchedules.teaching;$('lateGrace').value=attendanceSchedules.graceMinutes}}
async function derivePassword(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:salt,iterations:210000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits)).map(b=>b.toString(16).padStart(2,'0')).join('')}
async function verifyAdmin(password){const record=await getSetting('admin-credentials');if(!record?.value)return false;const salt=Uint8Array.from(record.value.salt.match(/.{2}/g),x=>parseInt(x,16));return (await derivePassword(password,salt))===record.value.hash}
async function createAdminPassword(password){const salt=crypto.getRandomValues(new Uint8Array(16)),saltHex=Array.from(salt).map(b=>b.toString(16).padStart(2,'0')).join('');await saveSetting({key:'admin-credentials',value:{salt:saltHex,hash:await derivePassword(password,salt)},updatedAt:new Date().toISOString()})}
