async function renderAdmin(){await initialSync;const workspace=syncSession()?.user?await currentWorkspace():null,cloudAdmin=workspace?.role==='company_admin',record=await getSetting('admin-credentials'),unlocked=cloudAdmin||adminUnlocked;$('adminLocked').classList.toggle('hidden',unlocked);$('adminContent').classList.toggle('hidden',!unlocked);$('adminAuthTitle').textContent=record?'Admin password':'Set admin password';$('adminAuthHelp').textContent=record?'Enter your administrator password to manage company settings.':'Create a password to protect company settings and employee management.';$('adminPasswordConfirmLabel').classList.toggle('hidden',!!record);$('adminUnlockButton').textContent=record?'Unlock admin':'Create admin password';if(!unlocked)return;await loadSchedules(true);const profile=await getSetting('company-profile');$('companyNameInput').value=profile?.value?.name||'Digital Attendance';$('companyPhone').value=profile?.value?.phone||'';$('companyEmail').value=profile?.value?.email||'';$('companyAddress').value=profile?.value?.address||'';const policy=(await getSetting('attendance-policy'))?.value||{};$('holidayDates').value=(policy.holidayDates||[]).join(', ');$('sandwichRule').checked=!!policy.sandwichRule;$('lateDaysPerAbsence').value=policy.lateDaysPerAbsence||2;const employees=(await all('employees')).sort((a,b)=>a.name.localeCompare(b.name));$('adminEmployeeSchedule').innerHTML=employees.length?'<table><thead><tr><th>Employee</th><th>Category</th><th>Assigned start time</th><th>Status</th></tr></thead><tbody>'+employees.map(e=>{const category=e.scheduleCategory||'peon';return '<tr><td>'+escapeHtml(e.name)+'</td><td>'+escapeHtml(categoryName(category))+'</td><td>'+escapeHtml(attendanceSchedules[category]||'08:00')+'</td><td>'+(e.active?'Active':'Inactive')+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Add employees to see their assigned schedule here.</div>'}
async function requireAdmin(){const session=syncSession();if(session?.user||localStorage.getItem('da_local_workspace_owner')){const access=await checkWorkspacePermission('settings.write');if(!access.allowed){notify(access.reason||'Company Admin access is required.');return false}return true}if(adminUnlocked)return true;showView('admin');notify('Admin password is required for employee changes.');return false}
async function ensurePermission(permission){const access=await checkWorkspacePermission(permission);if(!access.allowed)notify(access.reason||'Your company role does not allow this action.');return access.allowed}
async function saveAdminSettings(){if(!await requireAdmin())return;if(!$('companyNameInput').value.trim()){notify('Enter the company name.');return}const grace=Number($('lateGrace').value),lateDays=Number($('lateDaysPerAbsence').value);if(!Number.isInteger(grace)||grace<0||grace>1440){notify('Grace period must be 0 to 1440 whole minutes.');return}if(!Number.isInteger(lateDays)||lateDays<1||lateDays>30){notify('Late-day rule must be 1 to 30.');return}attendanceSchedules={peon:$('timePeon').value||'08:00',management:$('timeManagement').value||'09:00',teaching:$('timeTeaching').value||'08:00',graceMinutes:grace};const holidayDates=[...new Set($('holidayDates').value.split(/[;,\s]+/).map(x=>x.trim()).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)))],policy={holidayDates,sandwichRule:$('sandwichRule').checked,lateDaysPerAbsence:lateDays};const now=new Date().toISOString();await saveSetting({key:'attendance-schedule',value:attendanceSchedules,updatedAt:now});await saveSetting({key:'attendance-policy',value:policy,updatedAt:now});await saveSetting({key:'company-profile',value:{name:$('companyNameInput').value.trim(),phone:$('companyPhone').value.trim(),email:$('companyEmail').value.trim(),address:$('companyAddress').value.trim()},updatedAt:now});if(syncSession()?.user)await updateWorkspaceCompanyName($('companyNameInput').value.trim());await updateCompanyName();notify('Company information and attendance rules saved.');await renderAdmin();await renderReport();await renderDashboard();syncNow()}
