function wireSync(){ $('createSyncAccount').onclick=async()=>{try{saveSyncConfig($('syncUrl').value,$('syncKey').value);const result=await syncSignup($('syncEmail').value,$('syncPassword').value);if(result.confirmationRequired){setSyncStatus({state:'Check email',message:'Confirm the Supabase email invitation, then sign in here and create the company workspace.'});return}$('syncPassword').value='';notify('Company account created. Create the company workspace next.');await createCompanyWorkspace($('workspaceCompanyName').value);await saveSetting({key:'company-profile',value:{name:$('workspaceCompanyName').value.trim()},updatedAt:new Date().toISOString()});await updateCompanyName();startRealtimeSync();await syncNow();await refreshTeamPanel()}catch(e){setSyncStatus({state:'Setup required',message:e.message})}};$('createWorkspace').onclick=async()=>{try{saveSyncConfig($('syncUrl').value,$('syncKey').value);localStorage.setItem('da_workspace_company_name',$('workspaceCompanyName').value.trim());const workspace=await createCompanyWorkspace($('workspaceCompanyName').value);await saveSetting({key:'company-profile',value:{name:$('workspaceCompanyName').value.trim()},updatedAt:new Date().toISOString()});await updateCompanyName();setSyncStatus({state:'Company ready',message:`${workspace.companyName} · this signed-in account is Company Admin.`});startRealtimeSync();await syncNow();await refreshTeamPanel()}catch(e){setSyncStatus({state:'Setup required',message:e.message})}};$('connectSync').onclick=async()=>{try{saveSyncConfig($('syncUrl').value,$('syncKey').value);localStorage.setItem('da_workspace_company_name',$('workspaceCompanyName').value.trim());await syncLogin($('syncEmail').value,$('syncPassword').value);$('syncPassword').value='';let workspace=await currentWorkspace({refresh:true});if(!workspace){const companyName=$('workspaceCompanyName').value.trim();if(companyName.length<2)throw new Error('Login ho gaya. Pehli dafa setup ke liye Company name bharein, phir dobara Connect / sign in dabayein.');try{workspace=await createCompanyWorkspace(companyName)}catch(err){const msg=String(err.message||err);if(/already has a company workspace/i.test(msg))throw new Error('Login sahi hai, lekin yeh account company workspace se linked nahin. Pehle Admin account se login karein ya Admin se is email ko invite karwayein.');throw err}}startRealtimeSync();await syncNow();await refreshTeamPanel()}catch(e){setSyncStatus({state:'Sign-in needed',message:e.message})}};$('syncNow').onclick=syncNow;$('disconnectSync').onclick=()=>{syncLogout();renderSyncSettings();showView('sync')};$('refreshTeam').onclick=()=>refreshTeamPanel().catch(e=>$('teamStatus').textContent=e.message);$('inviteTeamUser').onclick=async()=>{try{await manageTeam('invite',{email:$('teamInviteEmail').value,role:$('teamInviteRole').value});$('teamInviteEmail').value='';$('teamStatus').textContent='Invitation sent. The user sets their own password from the email.';await refreshTeamPanel()}catch(e){$('teamStatus').textContent=e.message}};$('teamTable').addEventListener('click',async e=>{const pending=e.target.closest('[data-pending-conflict]'),role=e.target.closest('[data-team-save]'),active=e.target.closest('[data-team-active]'),device=e.target.closest('[data-team-device]'),adminDevice=e.target.closest('[data-team-admin-device]');try{if(pending){const c=teamPendingConflicts.find(x=>x.resolution_id===pending.dataset.pendingConflict);if(c){await resolveRemoteAttendanceConflict(c,pending.dataset.choice);notify('Conflict resolved.');await refreshTeamPanel()}return}else if(role){const select=$(`select[data-team-role="${CSS.escape(role.dataset.teamSave)}"]`);await manageTeam('member-update',{userId:role.dataset.teamSave,role:select.value,active:true})}else if(active){const select=$(`select[data-team-role="${CSS.escape(active.dataset.teamActive)}"]`);await manageTeam('member-update',{userId:active.dataset.teamActive,role:select.value,active:active.dataset.active==='true'})}else if(device){await manageTeam('device-update',{installationId:device.dataset.teamDevice,status:device.dataset.status})}else if(adminDevice){await manageTeam('set-admin-device',{installationId:adminDevice.dataset.teamAdminDevice})}else return;await refreshTeamPanel()}catch(err){$('teamStatus').textContent=err.message}});$('registerLicenseDevice').onclick=async()=>{try{const result=await licenseRequest('register-device');localStorage.setItem('da_license_customer_id',result.customerId);$('licenseStatus').textContent=`Customer ${result.customerId} · device ${result.deviceStatus} · offline window: up to ${result.offlineDays} days.`;notify(result.customerStatus==='active'&&result.deviceStatus==='active'?'License verified.':'Owner approval or an active license is required.')}catch(e){$('licenseStatus').textContent=e.message}};$('refreshLicenseOwner').onclick=loadLicenseOwner;$('licenseOwnerTable').addEventListener('click',async e=>{const c=e.target.closest('[data-license-customer]'),d=e.target.closest('[data-license-device]');if(!c&&!d)return;try{if(c)await licenseRequest('owner-customer-status',{customerId:c.dataset.licenseCustomer,status:c.dataset.licenseStatus});if(d){const approve=d.dataset.licenseStatus==='approve';await licenseRequest(approve?'approve-device':'owner-device-status',{deviceId:d.dataset.licenseDevice,status:d.dataset.licenseStatus})}await loadLicenseOwner()}catch(err){$('licenseStatus').textContent=err.message}});window.addEventListener('da:sync-status',e=>{setSyncStatus(e.detail);const denied=e.detail?.state==='Sync error'&&/device is not active|membership is inactive|not linked to the company workspace|no active company membership/i.test(e.detail.message||'');if(denied&&localStorage.getItem('da_local_workspace_owner')&&!isCurrentAdminBackupDevice()){document.body.classList.add('workspace-access-denied');showView('sync')}else if(e.detail?.state==='Synced')document.body.classList.remove('workspace-access-denied')});window.addEventListener('da:data-updated',async()=>{await loadSchedules(false);await updateCompanyName();await renderDashboard();if($('view-employees').classList.contains('active'))await renderEmployees();if($('view-reports').classList.contains('active'))await renderReport();if($('view-sync').classList.contains('active'))await refreshTeamPanel()});window.addEventListener('online',()=>{startRealtimeSync();syncNow()});setInterval(()=>{if(navigator.onLine)syncNow()},15000)}
function beep(){try{const context=new AudioContext(),osc=context.createOscillator(),gain=context.createGain();osc.connect(gain);gain.connect(context.destination);osc.frequency.value=880;gain.gain.value=.045;osc.start();osc.stop(context.currentTime+.12);osc.onended=()=>context.close()}catch{}}
async function scanFrame(){if(!scanning||loopBusy)return;loopBusy=true;try{const method=$('scanMethod').value,employees=await all('employees');if(method!=='qr'&&isFaceReady()){const match=await identifyFace($('scanVideo'),employees);if(match)await processEmployee(match.employee,'Face')}if(method!=='face'&&barcodeDetector&&$('scanVideo').readyState>=2){const codes=await barcodeDetector.detect($('scanVideo'));if(codes.length){const id=parseQr(codes[0].rawValue),employee=employees.find(e=>e.id===id);if(employee)await processEmployee(employee,'QR');else showFeedback('Unknown employee','This QR code is not registered on this device.')}}}catch(e){console.warn(e)}finally{loopBusy=false;if(scanning)setTimeout(scanFrame,350)}}
function parseQr(raw){const text=String(raw||'').trim();try{if(text.startsWith('DIGITAL-ATTENDANCE:'))return decodeURIComponent(text.slice('DIGITAL-ATTENDANCE:'.length));if(text.startsWith('DA|'))return text.slice(3);const j=JSON.parse(text);if(j.app==='Digital Attendance'&&typeof j.employeeId==='string')return j.employeeId}catch{}return text||null}
function csvEscape(v){return `"${String(v??'').replace(/"/g,'""')}"`}
function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function csvFile(){const records=await all('attendance'),data=[['Employee ID','Employee Name','Date','Attendance Status','Check-in Time','Late by minutes','Check-out Time','Check-in Method','Check-out Method'],...records.sort((a,b)=>a.date.localeCompare(b.date)||a.employeeId.localeCompare(b.employeeId)).map(a=>[a.employeeId,a.employeeName,a.date,a.status,a.checkIn,a.lateMinutes||0,a.checkOut,a.method,a.checkOutMethod])];return new File(['\ufeff'+data.map(row=>row.map(csvEscape).join(',')).join('\r\n')],`digital-attendance-${localDate()}.csv`,{type:'text/csv;charset=utf-8'})}
